l:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/anemohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/anemohelix_ii.lua",["SHA256"]="fb41cfd78572c29fa1e8275994fb82a7bd2c20e2514cca7a2a5edb27599ae7f1",["Text"]="-----------------------------------\n-- Spell: Anemohelix II\n-- Deals wind damage that gradually reduces target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/aspir.lua"]={["Path"]="scripts/actions/spells/black/aspir.lua",["SHA256"]="6de7ddebd8fc5c4cf8f5060d0b3f6c01b292c3e4a051287106e9c3798a1b91ea",["Text"]="-----------------------------------\n-- Spell: Aspir\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doDrainingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/aspir_ii.lua"]={["Path"]="scripts/actions/spells/black/aspir_ii.lua",["SHA256"]="6de7ddebd8fc5c4cf8f5060d0b3f6c01b292c3e4a051287106e9c3798a1b91ea",["Text"]="-----------------------------------\n-- Spell: Aspir\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.absorb.doDrainingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bind.lua"]={["Path"]="scripts/actions/spells/black/bind.lua",["SHA256"]="80e91502c3da52cb4580991b6c0a11e8e2181ee049da135b9ad9a3edd6675270",["Text"]="-----------------------------------\n-- Spell: Bind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bindga.lua"]={["Path"]="scripts/actions/spells/black/bindga.lua",["SHA256"]="00b734b72b79cab71848eab64fd687be8a57c98a98b8ef1b190271f69b697ba7",["Text"]="-----------------------------------\n-- Spell: Bindga\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bio.lua"]={["Path"]="scripts/actions/spells/black/bio.lua",["SHA256"]="dbd5d779483139e6b3c412b4b0673aeca050f9c7794339659b99405f2c22b56c",["Text"]="-----------------------------------\n-- Spell: Bio\n-- Deals dark damage that weakens an enemy's attacks and gradually reduces its HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 2\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n\n        -- Calculate DoT effect: http://wiki.ffo.jp/html/1954.html\n        local power = caster:getSkillLevel(xi.skill.DARK_MAGIC)\n        power       = math.ceil(power / 40)\n        power       = utils.clamp(power, 1, 3)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = 60, origin = caster, tick = 3, subPower = 10, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bio_ii.lua"]={["Path"]="scripts/actions/spells/black/bio_ii.lua",["SHA256"]="34b727902e4f3a7acd1ef30f59a67235e7f385e99e23acb9174dfae28cb10b55",["Text"]="-----------------------------------\n-- Spell: Bio II\n-- Deals dark damage that weakens an enemy's attacks and gradually reduces its HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 4\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n\n        -- Calculate DoT effect: http://wiki.ffo.jp/html/1954.html\n        local power = caster:getSkillLevel(xi.skill.DARK_MAGIC)\n        power       = math.floor((power + 29) / 40)\n        power       = utils.clamp(power, 3, 8)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = 120, origin = caster, tick = 3, subPower = 15, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bio_iii.lua"]={["Path"]="scripts/actions/spells/black/bio_iii.lua",["SHA256"]="5c34c79d77f910bc655ba6579266ef77d6c5f95779370cb2e34290505f962628",["Text"]="-----------------------------------\n-- Spell: Bio III\n-- Deals dark damage that weakens an enemy's attacks and gradually reduces its HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 6\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n\n        -- Calculate DoT effect: http://wiki.ffo.jp/html/1954.html\n        local power      = 0\n        local skillLevel = caster:getSkillLevel(xi.skill.DARK_MAGIC)\n        if skillLevel > 291 then\n            power = 13 + math.floor((skillLevel - 291) / 27) -- 13 + 1 every 27 skill levels.\n        elseif skillLevel > 246 then\n            power = 9 + math.floor((skillLevel - 246) / 11) -- 9 + 1 every 11 skill levels.\n        else\n            power = 5 + math.floor((skillLevel - 106) / 35) -- 5 + 1 every 35 skill levels.\n        end\n\n        power = utils.clamp(power, 5, 17)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = 180, origin = caster, tick = 3, subPower = 20, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bio_iv.lua"]={["Path"]="scripts/actions/spells/black/bio_iv.lua",["SHA256"]="e0b20118e97079ae74d7ea0de479b8b1418a408865da9a55edb82e3c5bda0873",["Text"]="-----------------------------------\n-- Spell: Bio IV\n-- Deals dark damage that weakens an enemy's attacks and gradually reduces its HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 8\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n\n        -- Calculate DoT effect (rough, though fairly accurate)\n        local power = 5 + math.floor(caster:getSkillLevel(xi.skill.DARK_MAGIC) / 60)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = 180, origin = caster, tick = 3, subPower = 25, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/bio_v.lua"]={["Path"]="scripts/actions/spells/black/bio_v.lua",["SHA256"]="ae53290e3e7f3e989a491d3ccc4f8c80e983cad0fd1d3866aa77afc3da665634",["Text"]="-----------------------------------\n-- Spell: Bio V\n-- Deals dark damage that weakens an enemy's attacks and gradually reduces its HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 10\n\n    -- Check for Dia.\n    local dia = target:getStatusEffect(xi.effect.DIA)\n    if\n        not dia or\n        (dia and dia:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.DIA)\n\n        -- Calculate DoT effect (rough, though fairly accurate)\n        local power = 5 + math.floor(caster:getSkillLevel(xi.skill.DARK_MAGIC) / 50)\n\n        target:addStatusEffect(xi.effect.BIO, { power = power, duration = 180, origin = caster, tick = 3, subPower = 25, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/blaze_spikes.lua"]={["Path"]="scripts/actions/spells/black/blaze_spikes.lua",["SHA256"]="44f8af0403340f94aa5a464365680d555d30536c0eb43bda9325fba1846419cc",["Text"]="-----------------------------------\n-- Spell: Blaze Spikes\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/blind.lua"]={["Path"]="scripts/actions/spells/black/blind.lua",["SHA256"]="74e6505ba02ad1cf817174e094eee6289a434104ad0574694a83790449b21343",["Text"]="-----------------------------------\n-- Spell: Blind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/blind_ii.lua"]={["Path"]="scripts/actions/spells/black/blind_ii.lua",["SHA256"]="c8f6ef17be6aa93991dfa5b4f386f93d952897eba50074ad8976626b64444af5",["Text"]="-----------------------------------\n-- Spell: Blind II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/blind